import{_ as e,o as r,c as a,a5 as i}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"Same-Colour Gems","description":"","frontmatter":{"title":"Same-Colour Gems","identification":"same-color-gems"},"headers":[],"relativePath":"identification/same-color-gems.md","filePath":"identification/same-color-gems.md","lastUpdated":1789241305000}'),o={name:"identification/same-color-gems.md"};function s(d,t,n,l,c,h){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="same-colour-gems" tabindex="-1">Same-Colour Gems <a class="header-anchor" href="#same-colour-gems" aria-label="Permalink to &quot;Same-Colour Gems&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>One colour can hide many species — red may be ruby, spinel, garnet, or glass. Combining RI / SG / pleochroism / inclusions eliminates candidates one by one. The trees below cover the three most confusing families: red, blue, and green.</p><h2 id="identification-steps" tabindex="-1">Identification Steps <a class="header-anchor" href="#identification-steps" aria-label="Permalink to &quot;Identification Steps&quot;">​</a></h2><p><strong>1. Measure the refractive index (RI)</strong> with a refractometer.</p><table tabindex="0"><thead><tr><th>RI reading</th><th>Likely family</th><th>Next</th></tr></thead><tbody><tr><td>1.76</td><td>Corundum (ruby / sapphire)</td><td>Step 2</td></tr><tr><td>1.71–1.72</td><td>Possible spinel</td><td>Cross-check SG, inclusions, and spectroscopy</td></tr><tr><td>1.74–1.89</td><td>Possible garnet</td><td>Cross-check SG, inclusions, and spectroscopy</td></tr><tr><td>1.5–1.7, glassy</td><td>Possible glass</td><td>Step 3</td></tr></tbody></table><p><strong>2. For corundum, check UV fluorescence</strong> under a LW lamp.</p><table tabindex="0"><thead><tr><th>Fluorescence</th><th>Conclusion</th></tr></thead><tbody><tr><td>Strong red</td><td>Supports a ruby candidate; cross-check</td></tr><tr><td>Weak or none</td><td>Does not exclude ruby; test further</td></tr></tbody></table><p><strong>3. For a glassy stone, look for bubbles / swirls.</strong></p><table tabindex="0"><thead><tr><th>Observation</th><th>Conclusion</th></tr></thead><tbody><tr><td>Bubbles or flow lines</td><td>Supports a glass imitation candidate</td></tr><tr><td>None</td><td>Does not exclude an imitation; re-check and add tests</td></tr></tbody></table><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Red: ruby RI 1.76 + strong red fluor.; spinel 1.71–1.72 none; garnet 1.74–1.89.</li><li>Blue: sapphire 1.76 dichroic blue/green; tanzanite 1.69–1.70 strongly trichroic; iolite 1.54 trichroism extreme.</li><li>Green: emerald 1.57–1.58 (oiled fissures); tsavorite 1.89 high dispersion; peridot 1.65–1.69 (doubling).</li><li>Fluorescence is only a screening clue: natural ruby may show strong LW red, but intensity varies with origin, treatment, and sample; synthetics can overlap.</li><li>No single observation replaces laboratory identification; use UV, scratch, and liquid tests only with appropriate equipment and safety procedures.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>RI 1.76 + red fluor.</td><td>vs spinel 1.72</td></tr><tr><td>sapphire</td><td>RI 1.76, no pleochroism</td><td>vs tanzanite 1.69 trichroic</td></tr><tr><td>emerald</td><td>RI 1.57 + oil fissures</td><td>vs tsavorite 1.89</td></tr></tbody></table><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>',15)])])}const m=e(o,[["render",s]]);export{u as __pageData,m as default};
